tool_input.command:
mkdir -p /tmp/fe04-scratch && cat > /tmp/fe04-scratch/overdue.scratch.test.js <<'EOF'
'use strict';
// Scratch verification for FE-04 only; not part of the repository. FE-05 owns the real tests.
const test = require('node:test');
const assert = require('node:assert');
const portal = require('ap_portal');

const FS1 = [
  { id: 'SYN-INV-004', vendor: 'Synthetic Vendor A', days: 75, amount: '1250.00', risk: 'high' },
  { id: 'SYN-INV-002', vendor: 'Synthetic Vendor B', days: 42, amount: '980.50', risk: 'medium' },
  { id: 'SYN-INV-003', vendor: 'Synthetic Vendor D', days: 42, amount: '15.00', risk: 'unknown' },
  { id: 'SYN-INV-001', vendor: 'Synthetic Vendor C', days: 31, amount: '300.00', risk: 'low' },
];
const FS1_HTML = '<table class="overdue-risk">'
  + '<tr><th>Invoice</th><th>Vendor</th><th>Days overdue</th><th>Amount</th></tr>'
  + '<tr class="risk-high"><td>SYN-INV-004</td><td>Synthetic Vendor A</td><td>75</td><td class="amount">1250.00</td></tr>'
  + '<tr class="risk-medium"><td>SYN-INV-002</td><td>Synthetic Vendor B</td><td>42</td><td class="amount">980.50</td></tr>'
  + '<tr class="risk-unknown"><td>SYN-INV-003</td><td>Synthetic Vendor D</td><td>42</td><td class="amount">15.00</td></tr>'
  + '<tr class="risk-low"><td>SYN-INV-001</td><td>Synthetic Vendor C</td><td>31</td><td class="amount">300.00</td></tr>'
  + '</table>';
const row = (o) => ({ id: 'SYN-INV-009', vendor: 'Synthetic Vendor E', days: 31, amount: '1.00', risk: 'low', ...o });

test('FS-1 exact output', () => assert.strictEqual(portal.renderOverdueRisk(FS1), FS1_HTML));
test('empty', () => {
  for (const v of [[], undefined, null]) assert.strictEqual(portal.renderOverdueRisk(v), '');
  assert.strictEqual(portal.renderOverdueRisk(), '');
});
test('non-array throws', () => {
  for (const v of ['[]', {}, 0]) assert.throws(() => portal.renderOverdueRisk(v), TypeError);
});
test('amounts', () => {
  const big = '123456789012345678901234567890.12';
  assert.ok(portal.renderOverdueRisk([row({ amount: big })]).includes(`<td class="amount">${big}</td>`));
  assert.ok(portal.renderOverdueRisk([row({ amount: '980.5' })]).includes('>980.50<'));
  assert.ok(portal.renderOverdueRisk([row({ amount: '980' })]).includes('>980.00<'));
  assert.ok(portal.renderOverdueRisk([row({ amount: '-5.1' })]).includes('>-5.10<'));
  for (const a of [12, '1e3', '1,250.00', '1.234', '', null, '.5', '5.']) {
    assert.throws(() => portal.renderOverdueRisk([row({ amount: a })]), TypeError, String(a));
  }
});
test('days', () => {
  for (const d of [31.5, '31', null, undefined, NaN]) assert.throws(() => portal.renderOverdueRisk([row({ days: d })]), TypeError);
});
test('escaping and risk allow-list', () => {
  const html = portal.renderOverdueRisk([row({ id: `<i>&"'`, vendor: 'Synthetic Vendor <E>', risk: 'x" onclick="' })]);
  assert.ok(html.includes('<td>&lt;i&gt;&amp;&quot;&#39;</td>'));
  assert.ok(html.includes('<td>Synthetic Vendor &lt;E&gt;</td>'));
  assert.ok(html.includes('<tr class="risk-unknown">'));
  assert.ok(!html.includes('onclick'));
  assert.ok(!/Late/.test(html));
});
test('exports', () => {
  assert.deepStrictEqual(Object.keys(portal), ['VERSION', 'LABELS', 'formatAmount', 'renderAgingSummary', 'renderOverdueRisk']);
  assert.strictEqual(portal.VERSION, '2.4.0');
});
EOF
cd ap-portal-sample && NODE_PATH=src node --test --experimental-test-coverage '--test-coverage-include=src/**' tests/portal.test.js /tmp/fe04-scratch/overdue.scratch.test.js 2>&1 | grep -E '^# (tests|pass|fail)|index.js|all files|not ok'
